mapper.select:
select d.ID_ as row_id,
       d.TEXT_ as stored_text,
       b.BYTES_ as stored_bytes
from ACT_HI_DETAIL d
left join ACT_GE_BYTEARRAY b on b.ID_ = d.BYTEARRAY_ID_
where d.PROC_INST_ID_ = #{processInstanceId}
  and d.NAME_ = #{variableName}
  and d.ID_ in

      #{rowId}

order by d.ID_

select v.ID_ as variable_id, v.PROC_INST_ID_ as process_instance_id, v.EXECUTION_ID_ as execution_id, v.TASK_ID_ as task_id, v.SUB_SCOPE_ID_ as sub_scope_id, v.NAME_ as variable_name, v.VAR_TYPE_ as variable_type_name, v.BYTEARRAY_ID_ as byte_array_id, case when v.TEXT_ is null then 0 else 1 end as text_present, case when v.TEXT2_ is null then 0 else 1 end as text2_present, octet_length(v.TEXT_) as text_bytes, case when b.ID_ is null then 0 else 1 end as byte_array_present, case when b.BYTES_ is null then 0 else 1 end as byte_array_body_present, octet_length(b.BYTES_) as stored_bytes from ACT_HI_VARINST v left join ACT_GE_BYTEARRAY b on b.ID_ = v.BYTEARRAY_ID_ where v.PROC_INST_ID_ = #{processInstanceId} and v.NAME_ in
#{variableName}
and v.TASK_ID_ = #{taskId}
and v.TASK_ID_ is null and v.EXECUTION_ID_ = v.PROC_INST_ID_ and v.SUB_SCOPE_ID_ is null
order by v.NAME_, v.ID_ limit #{rowLimit}

select v.ID_ as row_id, v.TEXT_ as stored_text, b.BYTES_ as stored_bytes from ACT_HI_VARINST v left join ACT_GE_BYTEARRAY b on b.ID_ = v.BYTEARRAY_ID_ where v.PROC_INST_ID_ = #{processInstanceId} and v.NAME_ in
#{variableName}
and v.ID_ in
#{rowId}
and v.TASK_ID_ = #{taskId}
and v.TASK_ID_ is null and v.EXECUTION_ID_ = v.PROC_INST_ID_ and v.SUB_SCOPE_ID_ is null
order by v.ID_
